import * as THREE from 'three';

// Generated by scripts/build-hand-assets.mjs. Keep topology generation off
// the browser's main thread; the binary is local and only loaded with scan.
export async function loadHandAssets(name='hands-v1') {
  const compressed = typeof DecompressionStream !== 'undefined';
  const response = await fetch(`${import.meta.env?.BASE_URL || '/'}models/${name}.bin${compressed ? '.gz' : ''}`);
  if (!response.ok) throw new Error('Hand geometry could not be loaded');
  // Fetch may already decode Content-Encoding. Inspect delivered bytes so both
  // encoded HTTP responses and ordinary static .gz downloads work correctly.
  let buffer = await response.arrayBuffer();
  const signature = new Uint8Array(buffer, 0, Math.min(2, buffer.byteLength));
  if (signature[0] === 0x1f && signature[1] === 0x8b) {
    buffer = await new Response(new Blob([buffer]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
  }
  const view = new DataView(buffer);
  let offset = 0;
  const uint = () => { const n=view.getUint32(offset,true);offset+=4;return n; };
  if(uint()!==0x48414e44 || uint()!==1)throw new Error('Unsupported hand geometry');
  const result=[];
  for(let i=0;i<4;i++){
    const n=uint(), indices=uint(), uv=uint(), g=new THREE.BufferGeometry();
    const attr=(name,Type,size)=>{const a=new Type(buffer,offset,n*size);offset+=a.byteLength;g.setAttribute(name,new THREE.BufferAttribute(a,size));};
    attr('position',Float32Array,3);attr('normal',Float32Array,3);attr('skinIndex',Uint16Array,4);attr('skinWeight',Float32Array,4);
    if(uv)attr('uv',Float32Array,2);
    g.setIndex(new THREE.BufferAttribute(new Uint32Array(buffer,offset,indices),1));offset+=indices*4;
    result.push(g);
  }
  return result;
}
